if record.quotation_type == 'Project':
  onhand_qty = 0
  qty_short = 0
  re_wh = False
  status = True 
  if record.product_status != 'Blank':
    so_loc = env['stock.warehouse'].search([('id', '=', record.warehouse_id.id)],limit=1)
    if so_loc:
      for sup_lines in so_loc.resupply_wh_ids:
        for routes in record.product_template_id.route_ids:
          if routes.supplier_wh_id:
            if routes.supplier_wh_id.id == sup_lines.id:
              if routes.supplied_wh_id.id == record.warehouse_id.id:
                onhand = env['stock.quant'].search([('product_tmpl_id', '=', record.product_template_id.id),('location_id', '=', routes.supplier_wh_id.lot_stock_id.id)], limit=1)
                if onhand:
                  onhand_qty = onhand.available_quantity
              re_wh = routes.supplier_wh_id.id

    if record.product_template_id.detailed_type == 'service':
      qty_short = 0
    else:
      if record.product_uom_qty > onhand_qty:
        qty_short = (record.product_uom_qty - onhand_qty)
        status = False
    record.write({'cost_value': record.product_template_id.standard_price, 'sales_warehouse_id': re_wh, 'current_onhand': onhand_qty, 'inventory_shortage': qty_short, 'cost_amount_req_qty': (record.product_uom_qty * record.product_template_id.standard_price), 'cost_amount_inventory_shortage': (qty_short * record.product_template_id.standard_price), 'invt_status': status})
else:
   record.write({'cost_value': 0, 'sales_warehouse_id': False, 'current_onhand': 0, 'inventory_shortage': 0, 'cost_amount_req_qty': 0, 'cost_amount_inventory_shortage': 0, 'invt_status': False})

